def solve_sudoku(board):
    """
    Solves a Sudoku puzzle using backtracking algorithm.

    Args:
        board (list of list of str): 9x9 Sudoku board where empty cells are represented by '.'

    Returns:
        list of list of str: Solved Sudoku board
    """
    def is_valid(row, col, val, board):
        """Check if placing val at (row, col) is valid according to Sudoku rules."""
        n = len(board)

        # Check row
        for i in range(n):
            if board[row][i] == val:
                return False

        # Check column
        for i in range(n):
            if board[i][col] == val:
                return False

        # Check 3x3 subgrid
        start_row = (row // 3) * 3
        start_col = (col // 3) * 3

        for i in range(start_row, start_row + 3):
            for j in range(start_col, start_col + 3):
                if board[i][j] == val:
                    return False

        return True

    def backtrack():
        """Recursive backtracking function to solve the Sudoku."""
        n = len(board)

        for i in range(n):
            for j in range(n):
                if board[i][j] != '.':
                    continue

                for val in range(1, 10):
                    val_str = str(val)
                    if is_valid(i, j, val_str, board):
                        board[i][j] = val_str

                        if backtrack():
                            return True
                        # Backtrack
                        board[i][j] = '.'

                # No valid value found for this cell
                return False

        # All cells filled successfully
        return True

    backtrack()
    return board
