        "code": "def main(response: str):
	import json
	from collections import defaultdict

	def build_tree(items):
		tree = defaultdict(lambda: {'files': [], 'dirs': {}})
		for item in items:
			path = item.get('path', '')
			item_type = item.get('type', '')
			parts = path.split('/')
			current = tree
			for i, part in enumerate(parts[:-1]):
				if part not in current['dirs']:
					current['dirs'][part] = {'files': [], 'dirs': {}}
				current = current['dirs'][part]
			if item_type == 'blob':
				current['files'].append(parts[-1])
			elif item_type == 'tree' and len(parts) == 1:
				if parts[0] not in current['dirs']:
					current['dirs'][parts[0]] = {'files': [], 'dirs': {}}
		return tree

	def format_tree(tree, prefix='', is_last=True):
		result = []
		dirs = sorted(tree['dirs'].items())
		files = sorted(tree['files'])
		items = [(name, True, content) for name, content in dirs] + [(name, False, None) for name in files]

		for idx, (name, is_dir, content) in enumerate(items):
			is_last_item = (idx == len(items) - 1)
			connector = '└── ' if is_last_item else '├── '
			result.append(f'{prefix}{connector}{name}/'if is_dir else f'{prefix}{connector}{name}')

			if is_dir and content:
				extension = '    ' if is_last_item else '│   '
				result.extend(format_tree(content, prefix + extension, is_last_item))

		return result

	try:
		data = json.loads(response)
		if 'tree' in data:
			tree_data = build_tree(data['tree'])
			lines = format_tree(tree_data)
			file_structure = '.\n' + '\n'.join(lines)
		else:
			file_structure = 'Error: Unable to retrieve file structure'
	except Exception as e:
		file_structure = f'Error: Failed to parse response - {str(e)}'

	return {
		'file_structure': file_structure
	}"
